import React, { useMemo, useRef, useEffect } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type HyperspaceFormulaProps = Record<string, any>;

// Seeded random number generator for stability
const random = (seed: number) => {
  const x = Math.sin(seed) * 10000;
  return x - Math.floor(x);
};

const FORMULA_LIST = [
  "E=mc²", "F=ma", "A = πr²", "c² = a² + b²",
  "x = (-b ± √(b² - 4ac)) / 2a",
  "∫ eˣ dx = eˣ + C", "∑ i = n(n+1)/2",
  "∇×E = -∂B/∂t", "HΨ = EΨ", "S = k log W",
  "CuCl₂", "H₂O", "CO₂", "C₆H₁₂O₆",
  "V_ab = I ∑(R+r) - ∑E",
  "A = EqΔI", "cos(A/2) = ±√(1+cosA)/2",
  "Sdx = x + C", "P(x) = (n!)/(x!(n-x)!) pˣ qⁿ⁻ˣ",
  "R_eq = R₁ + R₂ + R₃", "1/R_eq = 1/R₁ + 1/R₂",
  "lim(x→∞) (1 + 1/x)ˣ = e", "e^(iπ) + 1 = 0",
  "d/dx (sin x) = cos x", "λ = h / p",
  "F = G(m₁m₂)/r²", "V = IR", "P = IV"
];

const FONTS = ["Kalam", "Playfair Display"];

interface Particle {
  id: number;
  text: string;
  x: number;
  y: number;
  initialZ: number;
  speedVariation: number;
  fontSize: number;
  fontFamily: string;
  opacityMultiplier: number;
}

const HyperspaceFormula: React.FC<HyperspaceFormulaProps> = ({
  backgroundColor = "#000000",
  transparentBackground = false,
  formulaColor = "#ffffff",
  speedMultiplier = 1.0,
  glowIntensity = 0.6,
  scatterSpread = 1.5,
  durationInSeconds = 5,
}) => {
  useFontLoader(FONTS);

  const frame = useCurrentFrame();
  const { width, height } = useVideoConfig();

  const density = 50;
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Configuration for 3D projection
  const FOCAL_LENGTH = 25;
  const MIN_Z = -5;  // Just behind the camera
  const MAX_Z = 120; // Far in the distance
  const Z_RANGE = MAX_Z - MIN_Z;

  // Generate stable particle data
  const particles: Particle[] = useMemo(() => {
    const list: Particle[] = [];
    for (let i = 0; i < density; i++) {
      const spreadX = width * scatterSpread;
      const spreadY = height * scatterSpread;
      
      list.push({
        id: i,
        text: FORMULA_LIST[Math.floor(random(i * 10) * FORMULA_LIST.length)],
        x: (random(i * 11) - 0.5) * spreadX * 2,
        y: (random(i * 12) - 0.5) * spreadY * 2,
        initialZ: random(i * 13) * Z_RANGE + MIN_Z,
        speedVariation: 0.8 + random(i * 14) * 0.4, 
        fontSize: 40 + random(i * 15) * 120,
        fontFamily: FONTS[Math.floor(random(i * 16) * FONTS.length)],
        opacityMultiplier: 0.4 + random(i * 17) * 0.6,
      });
    }
    return list;
  }, [density, width, height, scatterSpread, Z_RANGE, MIN_Z]);

  const canvasRef = useRef(null);

  // Hardware-accelerated Canvas Rendering Engine
  // Replaces expensive DOM node recalculations and CSS repaints
  useEffect(() => {
    const canvas = canvasRef.current as HTMLCanvasElement | null;
    if (!canvas) return;
    
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    // Clear previous frame
    ctx.clearRect(0, 0, width, height);

    // Calculate dynamic state for all particles in current frame
    const particlesToDraw = particles.map(p => {
      const travelSpeed = 0.15 * speedMultiplier * p.speedVariation;
      const rawZ = p.initialZ - frame * travelSpeed;
      const currentZ = ((rawZ - MIN_Z) % Z_RANGE + Z_RANGE) % Z_RANGE + MIN_Z;

      const depthFactor = Math.max(0.1, FOCAL_LENGTH + currentZ);
      const scale = FOCAL_LENGTH / depthFactor;

      const projectedX = width / 2 + p.x * scale;
      const projectedY = height / 2 + p.y * scale;

      const opacityPoints = [MIN_Z, 0, MAX_Z * 0.7, MAX_Z];
      const opacityValues = [0, 1, 0.8, 0];
      
      const baseOpacity = interpolate(
        currentZ,
        opacityPoints,
        opacityValues,
        { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
      );
      const finalOpacity = baseOpacity * p.opacityMultiplier;

      return { ...p, currentZ, scale, projectedX, projectedY, finalOpacity };
    });

    // Painter's algorithm: draw particles furthest away first
    particlesToDraw.sort((a, b) => b.currentZ - a.currentZ);

    const baseShadowRadius = Math.max(2, Math.round(12 * glowIntensity));

    ctx.textAlign = "center";
    ctx.textBaseline = "middle";

    // Batch draw operations
    particlesToDraw.forEach(p => {
      if (p.finalOpacity <= 0) return;

      ctx.save();
      ctx.globalAlpha = p.finalOpacity;
      ctx.fillStyle = formulaColor;

      if (glowIntensity > 0) {
        ctx.shadowColor = formulaColor;
        // Scale shadow based on perspective depth
        ctx.shadowBlur = baseShadowRadius * p.scale;
      }

      ctx.translate(p.projectedX, p.projectedY);
      ctx.scale(p.scale, p.scale);

      ctx.font = `${p.fontSize}px "${p.fontFamily}"`;
      ctx.fillText(p.text, 0, 0);

      ctx.restore();
    });

  }, [frame, width, height, particles, formulaColor, glowIntensity, speedMultiplier]);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden" }}>
      <canvas 
        ref={canvasRef}
        width={width}
        height={height}
        style={{
          width: "100%",
          height: "100%",
          display: "block"
        }}
      />
    </AbsoluteFill>
  );
};

export default HyperspaceFormula;